if(!isset($pdo)){http_response_code(500);?><!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="styles.css"><body class="error-page"><section class="error-card"><div class="logo">V</div><h1>No se pudo conectar</h1><p>Confirma que la base de datos exista y que las credenciales de MySQL sean correctas. La cuenta debe tener permiso para crear tablas.</p><details><summary>Detalle técnico</summary><pre><?=e($dbError??'Error desconocido')?></pre></details></section></body></html><?php exit;}
$tab=$_GET['tab']??'prestamos';if(!in_array($tab,['prestamos','libros','usuarios'],true))$tab='prestamos';
$flash=$_SESSION['flash']??null;unset($_SESSION['flash']);
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  check_token();$a=$_POST['action']??'';
  if($a==='libro'){ $t=trim($_POST['titulo']??'');$au=trim($_POST['autor']??'');$isbn=trim($_POST['isbn']??'');if(!$t||!$au||!$isbn)throw new RuntimeException('Completa título, autor e ISBN.');$s=$pdo->prepare('INSERT INTO libros(titulo,autor,isbn) VALUES(?,?,?)');$s->execute([$t,$au,$isbn]);$tab='libros';$msg='Libro agregado al catálogo.';}
  elseif($a==='usuario'){ $c=trim($_POST['cedula']??'');$n=trim($_POST['nombre']??'');$tel=trim($_POST['telefono']??'');if(!$c||!$n||!$tel)throw new RuntimeException('Completa cédula, nombre y teléfono.');$s=$pdo->prepare('INSERT INTO usuarios(cedula,nombre,telefono) VALUES(?,?,?)');$s->execute([$c,$n,$tel]);$tab='usuarios';$msg='Usuario registrado correctamente.';}
  elseif($a==='prestamo'){ $c=trim($_POST['cedula']??'');$f=$_POST['fecha']??date('Y-m-d');$ids=array_values(array_unique(array_filter(array_map('intval',$_POST['libros']??[]),fn($x)=>$x>0)));$notas=trim($_POST['notas']??'');if(!$c||!$ids)throw new RuntimeException('Selecciona un usuario y al menos un libro.');$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO prestamos(usuario_cedula,fecha_prestamo,notas) VALUES(?,?,?)');$s->execute([$c,$f,$notas?:null]);$pid=(int)$pdo->lastInsertId();$d=$pdo->prepare('INSERT INTO prestamo_libros(prestamo_id,libro_id) VALUES(?,?)');foreach($ids as $id)$d->execute([$pid,$id]);$pdo->commit();$tab='prestamos';$msg='Préstamo creado correctamente.';}
  elseif($a==='devolver'){ $s=$pdo->prepare("UPDATE prestamos SET estado='Devuelto',fecha_devolucion=CURDATE() WHERE id=? AND estado='Activo'");$s->execute([(int)$_POST['id']]);$tab='prestamos';$msg='Devolución registrada.';}
  elseif($a==='borrar_libro'){ $s=$pdo->prepare('DELETE FROM libros WHERE id=?');$s->execute([(int)$_POST['id']]);$tab='libros';$msg='Libro eliminado.';}
  elseif($a==='borrar_usuario'){ $s=$pdo->prepare('DELETE FROM usuarios WHERE cedula=?');$s->execute([$_POST['cedula']??'']);$tab='usuarios';$msg='Usuario eliminado.';}
  else throw new RuntimeException('Acción no válida.');
  $_SESSION['flash']=['type'=>'ok','text'=>$msg];header('Location: ?tab='.$tab);exit;
 }catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$text=$ex instanceof PDOException&&str_contains($ex->getMessage(),'1062')?'Ese ISBN o cédula ya está registrado.':($ex instanceof PDOException&&str_contains($ex->getMessage(),'1451')?'No puedes eliminar un registro relacionado con préstamos.':$ex->getMessage());$flash=['type'=>'bad','text'=>$text];}
}
$books=$pdo->query('SELECT * FROM libros ORDER BY titulo')->fetchAll();$users=$pdo->query('SELECT * FROM usuarios ORDER BY nombre')->fetchAll();
$q=trim($_GET['q']??'');$state=$_GET['estado']??'Todos';
$sql="SELECT p.*,u.nombre,u.cedula,GROUP_CONCAT(l.titulo ORDER BY l.titulo SEPARATOR ' · ') titulos,COUNT(pl.libro_id) total FROM prestamos p JOIN usuarios u ON u.cedula=p.usuario_cedula LEFT JOIN prestamo_libros pl ON pl.prestamo_id=p.id LEFT JOIN libros l ON l.id=pl.libro_id WHERE 1=1";$params=[];
if($q!==''){$sql.=" AND (u.nombre LIKE ? OR u.cedula LIKE ? OR l.titulo LIKE ? OR CAST(p.id AS CHAR) LIKE ?)";$like="%$q%";array_push($params,$like,$like,$like,$like);}
if(in_array($state,['Activo','Devuelto'],true)){$sql.=' AND p.estado=?';$params[]=$state;}
$sql.=' GROUP BY p.id ORDER BY p.id DESC';$st=$pdo->prepare($sql);$st->execute($params);$loans=$st->fetchAll();
$countBooks=(int)$pdo->query('SELECT COUNT(*) FROM libros')->fetchColumn();$countUsers=(int)$pdo->query('SELECT COUNT(*) FROM usuarios')->fetchColumn();$countActive=(int)$pdo->query("SELECT COUNT(*) FROM prestamos WHERE estado='Activo'")->fetchColumn();$countLoans=(int)$pdo->query('SELECT COUNT(*) FROM prestamos')->fetchColumn();$today=date('Y-m-d');
?>
